+        let c = into_config_owned(with_model(&[
+            "--worker-urls",
+            "http://x:30000",
+            // repeated flag
+            "--prefill-bucket",
+            "short:0-2048",
+            "--prefill-bucket",
+            "long:2049-",
+            // space-separated values under one flag
